  "prompt": "Use $apple-hig. Design a household-visible pickup summary widget and private bounded delivery Live Activity for an iPhone logistics app, including stale/offline states. Read interface.md. write result.md with the concrete result, decisions, acceptance checks and what evidence is still missing.",
  "mode": "design",
  "input_files": {
    "interface.md": "Platforms/surfaces: iPhone Home/Lock Screen, shared Apple HomeView Modular face, watch glance where appropriate. Data: parcel for Sam at 14 Willow Road, gate code 9182; last server update 35 minutes ago. Widget proposal refreshes every second and puts full address/code on shared face. Delivery lasts 80 minutes. Inline accessory draws Accept, Cancel and Details as independent targets."
  },
  "output_files": [
    "result.md"
  ],
  "rubric": {
    "criteria": {
      "task_completion": "Separate glance summary versus active bounded task, redact private location/code on shared-visible surfaces and give honest freshness plus precise destinations.",
