      "artifact_usefulness": "Deliver a task-specific corrected artifact or evidence-grounded audit with worked states/transitions and observable checks; a generic checklist is insufficient.",
      "conditions_accessibility": "Preserve useful data when stale without calling it Live; rendering variants must retain meaning without color; shared and private contexts need explicit policy.",
      "evidence_honesty": "Do not invent native runtime results, unseen semantics, device support, measurements or source authority; distinguish source conflict and unresolved product constraints."
    },
    "critical_errors": [
      "Leaks full gate code/address on shared HomeView without deliberate protected policy.",
      "Promises continuous widget second-by-second refresh.",
      "Creates three independently tappable inline accessory targets."
    ]
  }
}

